/* Check if the set containing "Angel of Mercy" appeared on Magic: The Gathering Online */

SELECT DISTINCT c.setcode 
FROM cards c
JOIN set_translations st ON c.setcode = st.setcode
WHERE c.name LIKE '%Angel of Mercy%'
AND st.translation LIKE '%Magic%The%Gathering%Online%';

/* Calculate the percentage of French-language Story Spotlight cards */
WITH story_spotlight_cards AS (
    SELECT *
    FROM foreign_data
    WHERE name LIKE '%Story Spotlight%'
)
SELECT 
    ROUND((SUM(CASE WHEN language = 'French' THEN 1.0 ELSE 0 END) / COUNT(*)) * 100, 2) AS french_percentage
FROM story_spotlight_cards;
